class NeonFinishButton extends StatelessWidget {
  final bool isActive;
  final VoidCallback? onTap;

  const NeonFinishButton({super.key, required this.isActive, this.onTap});

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: isActive ? onTap : null,
      child: AnimatedSwitcher(
        duration: const Duration(milliseconds: 300),
        child: SizedBox(
          key: ValueKey<bool>(isActive),
          height: 102,
          width: double.infinity,
          child: SvgPicture.string(
            isActive ? _svgFinishActive : _svgFinishInactive,
            fit: BoxFit.fill,
          ),
        ),
      ),
    );
  }
}

// === КАСТОМНИЙ ВІДЖЕТ ДЗВОНИКА ДЛЯ СЛУЖБИ СПОВІЩЕНЬ ===
class NeonNotificationBell extends StatelessWidget {
  final bool hasUnread;      // Кейс 1 (false) - без крапки, Кейс 2 (true) - з зеленою крапкою
  final bool isOpen;         // Якщо true — сам дзвоник стає зеленим (#00F5A0), якщо false — білим (#FFFFFF)
  final VoidCallback onTap;   // Клік по дзвонику

  const NeonNotificationBell({
    super.key,
    required this.hasUnread,
    required this.isOpen,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    // Динамічно визначаємо колір ліній самого дзвоника
    final String bellColor = isOpen ? '#00F5A0' : '#FFFFFF';

    // 1 КЕЙС: Чистий білий/зелений дзвоник без крапки
    final String bellNormalSvg = '''
<svg width="18" height="24" viewBox="0 0 18 24" fill="none" xmlns="http://www.w3.org/2000/svg">
<path d="M6 21H12C12 21 12.15 24 9 24C5.85 24 6 21 6 21ZM16.05 17.1C15.3 16.8 15 16.05 15 15.3V7.5C15 7.5 14.7 3.9 10.5 3.15V1.5C10.5 1.5 10.65 0 9 0C7.35 0 7.5 1.5 7.5 1.5V3.15C3.3 3.9 3 7.5 3 7.5V15.3C3 16.05 2.55 16.8 1.95 17.1L0 18V19.5H18V18L16.05 17.1ZM6 7.2V18H3C4.2 18 4.5 16.5 4.5 16.5V7.5C4.5 7.5 4.5 6.3 5.55 5.4C6.6 4.35 7.5 4.5 7.5 4.5C7.5 4.5 6 5.55 6 7.2Z" fill="$bellColor"/>
</svg>
''';

    // 2 КЕЙС: Дзвоник із твоєю рідною зеленою крапкою (крапка завжди #00F5A0)
    final String bellActiveSvg = '''
<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
<path d="M6 21H12C12 21 12.15 24 9 24C5.85 24 6 21 6 21ZM16.05 17.1C15.3 16.8 15 16.05 15 15.3V7.5C15 7.5 14.7 3.9 10.5 3.15V1.5C10.5 1.5 10.65 0 9 0C7.35 0 7.5 1.5 7.5 1.5V3.15C3.3 3.9 3 7.5 3 7.5V15.3C3 16.05 2.55 16.8 1.95 17.1L0 18V19.5H18V18L16.05 17.1ZM6 7.2V18H3C4.2 18 4.5 16.5 4.5 16.5V7.5C4.5 7.5 4.5 6.3 5.55 5.4C6.6 4.35 7.5 4.5 7.5 4.5C7.5 4.5 6 5.55 6 7.2Z" fill="$bellColor"/>
<circle cx="20.2" cy="3.5" r="3.2" fill="#00F5A0"/>
</svg>
''';

    return GestureDetector(
      onTap: onTap,
      behavior: HitTestBehavior.opaque,
      child: Container(
        padding: const EdgeInsets.all(4),
        child: SvgPicture.string(
          hasUnread ? bellActiveSvg : bellNormalSvg,
          width: 18,
          height: 24,
        ),
      ),
    );
  }
}


